json_response(['success'=>true,'user'=>$u,'profile'=>$profile,'date'=>$date,'food'=>$food,'water'=>$water,'progress'=>$progress,'workouts'=>$workouts,'plans'=>$plans,'recipes'=>recipesFor($conn,$uid),'family'=>$family,'family_info'=>$fi]);
