if($w!==null&&$date<=date('Y-m-d')&&$date===$latest){$st=$conn->prepare('UPDATE user_profiles SET current_weight=? WHERE user_id=?');$st->bind_param('di',$w,$uid);$st->execute();$st->close();$p['current_weight']=$w;if($p['auto_targets']){ff_update_targets($conn,$uid,$p);$updated=true;}}
$conn->commit();json_response(['success'=>true,'targets_updated'=>$updated]);
}catch(InvalidArgumentException $e){$conn->rollback();json_response(['success'=>false,'message'=>$e->getMessage()],422);}catch(Throwable $e){$conn->rollback();error_log($e->getMessage());json_response(['success'=>false,'message'=>'Unable to save check-in. Check your profile settings.'],500);}}
