if($action==='recipe_add'){try{$weight=ff_cooked_weight($in['total_cooked_weight_g']??null);}catch(InvalidArgumentException $e){json_response(['success'=>false,'message'=>$e->getMessage()],422);}$in=ff_enrich_recipe($in);$name=trim($in['recipe_name']??'');if($name==='')json_response(['success'=>false,'message'=>'Recipe name is required.'],400);$ingredients=json_encode(array_values(array_filter($in['ingredients']??[])),JSON_UNESCAPED_UNICODE);$desc=$in['description']??null;$url=$in['source_url']??null;$image=clean_recipe_image_url($in['image_url']??'');$image=$image!==''?$image:null;$type=$in['source_type']??'manual';$inst=$in['instructions']??null;$serv=(float)($in['servings']??1);$prep=$in['prep_time_minutes']??null;$cook=$in['cook_time_minutes']??null;$cal=(float)($in['calories_per_serving']??0);$pro=(float)($in['protein_per_serving']??0);$cb=(float)($in['carbs_per_serving']??0);$fat=(float)($in['fat_per_serving']??0);$fiber=(float)($in['fiber_per_serving']??0);$fav=(int)($in['is_favorite']??0);$st=$conn->prepare("INSERT INTO recipes(user_id,recipe_name,description,source_url,image_url,source_type,ingredients,instructions,servings,prep_time_minutes,cook_time_minutes,calories_per_serving,protein_per_serving,carbs_per_serving,fat_per_serving,fiber_per_serving,is_favorite) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)");$st->bind_param("isssssssdiidddddi",$uid,$name,$desc,$url,$image,$type,$ingredients,$inst,$serv,$prep,$cook,$cal,$pro,$cb,$fat,$fiber,$fav);if(!$st->execute())json_response(['success'=>false,'message'=>'Unable to save recipe.'],500);$id=$conn->insert_id;$st->close();$category=$in['meal_category']??'any';if(!in_array($category,['any','breakfast','lunch','dinner','snack'],true))$category='any';$status=$in['nutrition_status']??'provided';if(!in_array($status,['provided','estimated','incomplete'],true))$status='incomplete';$notes=$in['nutrition_notes']??'';$st=$conn->prepare('UPDATE recipes SET meal_category=?,nutrition_status=?,nutrition_notes=?,total_cooked_weight_g=? WHERE id=? AND user_id=?');$st->bind_param('sssdii',$category,$status,$notes,$weight,$id,$uid);$st->execute();$st->close();json_response(['success'=>true]);}
if($action==='recipe_delete'){$id=(int)($in['id']??0);$st=$conn->prepare("DELETE FROM recipes WHERE id=? AND user_id=?");$st->bind_param("ii",$id,$uid);$st->execute();$st->close();json_response(['success'=>true]);}
if($action==='join_family'){$code=strtoupper(trim($in['invite_code']??''));if($code==='')json_response(['success'=>false,'message'=>'Enter a family code.'],400);$st=$conn->prepare("SELECT id FROM families WHERE invite_code=? LIMIT 1");$st->bind_param("s",$code);$st->execute();$f=$st->get_result()->fetch_assoc();$st->close();if(!$f)json_response(['success'=>false,'message'=>'Family code not found.'],404);$fid=(int)$f['id'];$st=$conn->prepare("SELECT 1 FROM family_members WHERE family_id=? AND user_id=?");$st->bind_param("ii",$fid,$uid);$st->execute();$st->store_result();$has=$st->num_rows>0;$st->close();if(!$has){$role='member';$st=$conn->prepare("INSERT INTO family_members(family_id,user_id,member_role) VALUES(?,?,?)");$st->bind_param("iis",$fid,$uid,$role);$st->execute();$st->close();}json_response(['success'=>true,'message'=>'Joined family successfully.']);}
json_response(['success'=>false,'message'=>'Unknown action.'],400);
